import{_ as t,o as i,c as h,a4 as a}from"./chunks/framework.CRKgIIuH.js";const d=JSON.parse('{"title":"Bài 1 — Thiết kế nghiên cứu và Kế hoạch quản lý dữ liệu (DMP)","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-1-dmp/index.md","filePath":"course/module-1-dmp/index.md"}'),o={name:"course/module-1-dmp/index.md"};function u(c,n,e,g,r,l){return i(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="bai-1-—-thiet-ke-nghien-cuu-va-ke-hoach-quan-ly-du-lieu-dmp" tabindex="-1">Bài 1 — Thiết kế nghiên cứu và Kế hoạch quản lý dữ liệu (DMP) <a class="header-anchor" href="#bai-1-—-thiet-ke-nghien-cuu-va-ke-hoach-quan-ly-du-lieu-dmp" aria-label="Permalink to &quot;Bài 1 — Thiết kế nghiên cứu và Kế hoạch quản lý dữ liệu (DMP)&quot;">​</a></h1><p><strong>Mục tiêu:</strong> viết được DMP 2 trang cho một nghiên cứu giả định; phân biệt được DMP, protocol và CRF.</p><h2 id="noi-dung-chinh" tabindex="-1">Nội dung chính <a class="header-anchor" href="#noi-dung-chinh" aria-label="Permalink to &quot;Nội dung chính&quot;">​</a></h2><p>Lớp kiểm soát bảo mật, đạo đức và pháp lý áp dụng xuyên suốt mọi giai đoạn của vòng đời dữ liệu.</p><p>Một nghiên cứu bắt đầu bằng câu hỏi lâm sàng, nhưng dữ liệu bắt đầu bằng <strong>Data Management Plan (DMP)</strong> — tài liệu mô tả dữ liệu nào sẽ thu thập, ở định dạng nào, lưu ở đâu, ai được truy cập, chia sẻ ra sao, và lưu bao lâu.</p><p>Nhà tài trợ lớn yêu cầu DMP từ lúc nộp hồ sơ. NIH yêu cầu <strong>Data Management and Sharing Plan (DMSP) ≤ 2 trang, 6 thành phần</strong>, chính sách có hiệu lực từ 25/01/2023; từ 25/02/2026, NIH ban hành mẫu tinh giản NOT-OD-26-046, bắt buộc với hồ sơ nộp từ 25/05/2026. Horizon Europe yêu cầu DMP đầy đủ chậm nhất vào tháng thứ 6 của dự án, theo nguyên tắc “mở tối đa có thể, đóng tối thiểu khi cần thiết”, dữ liệu mở theo CC BY/CC0.</p><p>Ba thứ thường bị nhầm với nhau:</p><ul><li><strong>Protocol (đề cương):</strong> nghiên cứu <em>làm gì, vì sao, trên ai</em>.</li><li><strong>DMP:</strong> dữ liệu <em>là gì, ở đâu, ai dùng, chia sẻ thế nào</em>.</li><li><strong>CRF / eCRF:</strong> biểu mẫu <em>thu thập từng trường dữ liệu</em> của từng người tham gia.</li></ul><p>Trước khi thu thập, cần thống nhất ba thứ: <strong>từ điển dữ liệu</strong> (mỗi biến nghĩa là gì, đơn vị nào, giá trị nào hợp lệ), <strong>Common Data Elements (CDE)</strong> — các biến chuẩn dùng chung để so sánh giữa các nghiên cứu, và <strong>metadata</strong> — dữ liệu mô tả dữ liệu (ai thu thập, khi nào, bằng công cụ nào, phiên bản nào). Không có metadata, dữ liệu sau 2 năm sẽ không ai hiểu nổi, kể cả chính người thu thập.</p><p><strong>Điểm cần nhớ:</strong> DMP có vòng đời riêng — soạn thảo, phê duyệt, rà soát định kỳ, cập nhật khi protocol thay đổi. DMP viết xong rồi cất tủ là DMP chết.</p>',10)])])}const p=t(o,[["render",u]]);export{d as __pageData,p as default};
